/** Ordered systems + fixed timestep tick. */

export type SystemContext = {
  dt: number;
  fixedDt: number;
  time: number;
};

export type GameSystem = {
  name: string;
  order?: number;
  init?: () => void | Promise<void>;
  fixedUpdate?: (ctx: SystemContext) => void;
  update?: (ctx: SystemContext) => void;
  dispose?: () => void;
};

export class SystemSchedule {
  private readonly systems: GameSystem[] = [];

  add(system: GameSystem): void {
    this.systems.push(system);
    this.systems.sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  }

  async initAll(): Promise<void> {
    for (const s of this.systems) {
      if (s.init) await s.init();
    }
  }

  fixedUpdate(ctx: SystemContext): void {
    for (const s of this.systems) s.fixedUpdate?.(ctx);
  }

  update(ctx: SystemContext): void {
    for (const s of this.systems) s.update?.(ctx);
  }

  disposeAll(): void {
    for (const s of [...this.systems].reverse()) s.dispose?.();
  }
}

export class Ticker {
  private acc = 0;
  private time = 0;
  private running = false;
  private raf = 0;
  readonly fixedDt: number;

  constructor(
    private readonly schedule: SystemSchedule,
    targetFps: number,
  ) {
    this.fixedDt = 1 / Math.max(30, Math.min(targetFps, 120));
  }

  start(onFrame?: (dt: number) => void): void {
    this.running = true;
    let last = performance.now();
    const loop = (now: number) => {
      if (!this.running) return;
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      this.acc += dt;
      this.time += dt;
      while (this.acc >= this.fixedDt) {
        this.schedule.fixedUpdate({ dt: this.fixedDt, fixedDt: this.fixedDt, time: this.time });
        this.acc -= this.fixedDt;
      }
      this.schedule.update({ dt, fixedDt: this.fixedDt, time: this.time });
      onFrame?.(dt);
      this.raf = requestAnimationFrame(loop);
    };
    this.raf = requestAnimationFrame(loop);
  }

  stop(): void {
    this.running = false;
    cancelAnimationFrame(this.raf);
  }
}
